local function ChasniAddRecipe(name, ingredients, config, tech)
    AddRecipe2(name, ingredients, tech or TECH.NONE, config, { "REWARD" })
end

local function ChasniAddIngredient(name, qty, xml, tex)
    name = name or "chasni_"..xml
    xml = xml or name
    tex = tex or xml
    return Ingredient(name, qty, "images/inventoryimages/"..xml..".xml", nil, tex..".tex")
end

